    const v = await ruler(r, testsBranch)
    if (v && v.ruled && v.branch) { r = await mk(', origin/' + v.branch + ' (ruling ' + v.row + ')'); r = { ...r, ruling: v } } else { r = { ...r, ruling: v } }
